/** Just the keys, e.g. ["manageDelegates", "exportData", "manageAccounts"]. */
export const PERM_KEYS = PERMISSIONS.map((p) => p.key);

/** Default tick state for a new account, e.g. { manageDelegates: true, ... }. */
export const DEFAULT_PERMISSIONS = Object.fromEntries(
  PERMISSIONS.map((p) => [p.key, !!p.default])
);

/**
 * Coerce any input into a clean { key: boolean } for every known key. A key
 * EXPLICITLY present (even `false`) wins — that's a saved admin decision. An
 * ABSENT key (account saved before the permission existed) falls back to its
 * declared `default`, NOT hardcoded false — see the `default` field doc above.
 */
export function cleanPermissions(input) {
  const out = {};
  for (const p of PERMISSIONS) {
    const present = !!input && Object.prototype.hasOwnProperty.call(input, p.key);
    out[p.key] = present ? !!input[p.key] : !!p.default;
  }
  return out;
}
